"""Value objects for refrigeration telemetry."""

from dataclasses import dataclass
from datetime import UTC, datetime


@dataclass(frozen=True)
class TelemetryEventId:
    """Stable identifier generated by an ESP32 for one measurement."""

    value: str

    def __post_init__(self) -> None:
        if not isinstance(self.value, str) or not self.value.strip():
            raise ValueError("Telemetry event ID cannot be empty")
        normalized = self.value.strip()
        if len(normalized) > 128:
            raise ValueError("Telemetry event ID cannot exceed 128 characters")
        object.__setattr__(self, "value", normalized)


@dataclass(frozen=True)
class RecordedAt:
    """UTC timestamp at which the ESP32 observed a measurement."""

    value: datetime

    def __post_init__(self) -> None:
        if not isinstance(self.value, datetime):
            raise TypeError("Recorded time must be a datetime")
        if self.value.tzinfo is None or self.value.utcoffset() is None:
            raise ValueError("Recorded time must include a timezone")
        object.__setattr__(self, "value", self.value.astimezone(UTC))
